UPDATE ai_config
SET tested_revision = #{revision},
    tested_at = CURRENT_TIMESTAMP(6),
    tested_by = #{testedBy}
WHERE org_id = #{orgId}
  AND connection_revision = #{revision}

UPDATE ai_config
SET enabled = #{enabled},
    operator_account_id = #{operatorAccountId},
    version = version + 1
WHERE org_id = #{orgId}
  AND version = #{expectedVersion}
